import type { Booking } from '@prisma/client';
import { bookingBatchConflict, bookingConflict, notFound, validationFailed } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { isBefore, MINUTE_IN_MS, parseInstant } from '../../shared/time.js';
import * as repository from './repository.js';
